package com.medtrack.medicine.dto; import com.medtrack.medicine.entity.Medicine; import java.time.Instant; import java.util.UUID; public record MedicineResponse(UUID id,String sku,String genericName,String brandName,String categoryCode,String dosageForm,String strength,String unitOfMeasure,String storageTemp,int minStockThreshold,int minReceivingShelfLifeDays,String status,String description,Instant createdAt,Instant updatedAt){public static MedicineResponse of(Medicine m){return new MedicineResponse(m.getId(),m.getSku(),m.getGenericName(),m.getBrandName(),m.getCategory().getCode(),m.getDosageForm(),m.getStrength(),m.getUnitOfMeasure(),m.getStorageTemp(),m.getMinStockThreshold(),m.getMinReceivingShelfLifeDays(),m.getStatus().name(),m.getDescription(),m.getCreatedAt(),m.getUpdatedAt());}}
